import{_ as t,o as a,c as s,ak as r}from"./chunks/framework.sV-XtlWr.js";const u=JSON.parse(`{"title":"Code reach","description":"Which tests execute each application source file, recorded from Chromium's JavaScript coverage and an ASP.NET Core backend's coverage on a scheduled run, and used by test selection, change coverage and preflight.","frontmatter":{"title":"Code reach","description":"Which tests execute each application source file, recorded from Chromium's JavaScript coverage and an ASP.NET Core backend's coverage on a scheduled run, and used by test selection, change coverage and preflight.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/code-reach.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/code-reach.html"}],["meta",{"property":"og:title","content":"Code reach | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Which tests execute each application source file, recorded from Chromium's JavaScript coverage and an ASP.NET Core backend's coverage on a scheduled run, and used by test selection, change coverage and preflight."}]]},"headers":[],"relativePath":"features/code-reach.md","filePath":"features/code-reach.md","lastUpdated":1792006319000}`),o={name:"features/code-reach.md"};function i(n,e,d,h,c,l){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="code-reach" tabindex="-1">Code reach <a class="header-anchor" href="#code-reach" aria-label="Permalink to &quot;Code reach&quot;">​</a></h1><p>&quot;Which tests reach this file?&quot; has an answer for test code from the locators a test calls. Code reach answers it for application code: an opt-in capture records the source files whose functions ran during each test, in the browser and, with an instrumented ASP.NET Core backend, on the <a href="#server-code">server</a>, so a change to a component or a module maps to the tests that execute it.</p><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><p>Set <code>captureCodeReach: true</code> in the reporter options, or <code>PIWI_CAPTURE_CODE_REACH=true</code>, with the <a href="/guide/capture-fixtures.html">capture fixtures</a> in place. Coverage adds time to every test and reach changes slowly, so turn it on in one scheduled job, a nightly run, rather than on every run. A run without it keeps the reach the last one recorded.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// playwright.config.ts, in the nightly job</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reporter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@piwitests/reporter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { captureCodeReach: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">process.env.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NIGHTLY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }]],</span></span></code></pre></div><h2 id="what-it-records" tabindex="-1">What it records <a class="header-anchor" href="#what-it-records" aria-label="Permalink to &quot;What it records&quot;">​</a></h2><p>The fixtures start Chromium&#39;s JavaScript coverage on the test&#39;s first page and, at teardown, turn each script into source files:</p><ul><li>a module a dev server serves by path (Vite&#39;s <code>/src/components/Pay.vue</code>, <code>/@fs/…</code>) is the file itself;</li><li>a bundle is read through its source map, inline or fetched once per worker (20 MB and 5 seconds at most).</li></ul><p>A file counts when one of its functions ran. A module&#39;s top-level code runs as soon as it is imported, so it does not count: otherwise every eagerly loaded file would be reached by every test. Paths are relative to the repository root; files under <code>node_modules</code> or outside the repository are dropped, and at most 2,000 files are kept per test. Only the paths leave the machine, never code, counts or line numbers.</p><p>Paths resolve against the Playwright config&#39;s directory, then the repository root. Set <code>codeReachRoots</code> to the dev server&#39;s root when it is elsewhere; for Nuxt that is <code>app/</code>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reporter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@piwitests/reporter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { captureCodeReach: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, codeReachRoots: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;app&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }]],</span></span></code></pre></div><p>Code a bundler or dev server adds (module wrappers, preload helpers, hot-reload hooks) maps to no source of its own and counts for no file.</p><p>When the backend is instrumented (the <a href="/guide/backend-logs.html">Nitro or ASP.NET Core packages</a>), the handler file of each route a test called also counts as reached, with no capture of its own.</p><h2 id="supported-builds" tabindex="-1">Supported builds <a class="header-anchor" href="#supported-builds" aria-label="Permalink to &quot;Supported builds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Build</th><th>Source maps</th></tr></thead><tbody><tr><td>Vite dev server, Nuxt dev included</td><td>none needed: modules are served by path</td></tr><tr><td>Vite build</td><td><code>build: { sourcemap: true }</code></td></tr><tr><td>Next.js dev, Turbopack or webpack</td><td>on by default</td></tr><tr><td>Next.js build, Turbopack or webpack</td><td><code>productionBrowserSourceMaps: true</code></td></tr><tr><td>webpack build</td><td><code>devtool: &#39;source-map&#39;</code></td></tr></tbody></table><p>The map must be linked from the bundle: <code>sourcemap: &#39;hidden&#39;</code> and webpack&#39;s <code>hidden-source-map</code> write the map but not the comment that names it, so they record nothing.</p><p>Each was checked on a React app with four components, a lazy-loaded one, a shared utility and a module imported on start but never called, with Vite 8, webpack 5.111 and Next.js 16.3: every test recorded exactly the files it ran, none missed and none extra. Nuxt dev was checked on Piwi&#39;s own suite. The same builds without source maps record nothing.</p><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><p>Code reach reads V8&#39;s function coverage, which records only whether each function ran, so the page&#39;s own JavaScript runs at nearly its usual speed. Each test pays for a CDP session with the debugger on, which reports every script&#39;s version, and for one coverage read at the end. A script&#39;s source is read once per worker, the first time a test loads that version of it. Measured on a 4-core sandbox (Xeon at 2.10 GHz, Ubuntu 24.04, Node 22, Playwright 1.63, headless Chromium), each configuration run in turn, round after round, medians:</p><ul><li><strong>A script-heavy page</strong> (Vue&#39;s development build rendering a 1,000-row table of components 30 times, plus 400 small ES modules; a new browser context per test, 15 rounds): a test goes from 1,128 ms to 1,220 ms, 8% more, and 16% more for a worker&#39;s first test, which reads all 403 sources. With two documents per test, 17% more. Playwright&#39;s <code>page.coverage</code>, which records block coverage and reads every script&#39;s source in every test, adds 50% and 54% on the same page, and reaches the same 137 files. Over three runs on a machine shared with other work, code reach added 5% to 23% to a test, <code>page.coverage</code> 44% to 55%.</li><li><strong>A light page</strong> (the reporter&#39;s capture benchmark, <code>npm run reporter:bench</code>, 12 tests of 20 actions and assertions): 61 ms and 103 ms more per test on top of the default capture in two runs, a median test going from 1,215 to 1,276 ms in one and from 1,140 to 1,242 ms in the other; <code>page.coverage</code> added 209 ms and 176 ms.</li></ul><p>The extra time grows with the number of scripts the page loads and the number of documents a test opens.</p><h2 id="server-code" tabindex="-1">Server code <a class="header-anchor" href="#server-code" aria-label="Permalink to &quot;Server code&quot;">​</a></h2><p>With an ASP.NET Core backend built for coverage, each test also records the backend code it ran:</p><ol><li>Add the <code>PiwiTests.Instrumentation.Coverage</code> package to every project whose code you want covered, as its <a href="https://github.com/PiwiTests/platform/tree/main/integrations/aspnetcore/PiwiTests.Instrumentation.Coverage#readme" target="_blank" rel="noreferrer">README</a> shows, serve it with <code>app.UsePiwiTestLogs()</code> (<a href="/guide/backend-logs.html">backend logs</a>), and build the test environment with <code>-p:PiwiCoverage=true</code>. Never ship that build to production.</li><li>Set the reporter&#39;s <code>coverage.server</code> option, or <code>PIWI_COVERAGE_SERVER</code>, with the capture fixtures in place.</li></ol><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reporter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@piwitests/reporter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { coverage: { server: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;lines&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }]],</span></span></code></pre></div><p>The backend names each request&#39;s coverage on its response. The fixtures keep the names a test&#39;s pages received; once the test ends, the reporter asks the backend for their coverage, several tests per call, outside the test&#39;s time, and the test&#39;s result reaches the dashboard with it.</p><table tabindex="0"><thead><tr><th><code>coverage.server</code></th><th>Records per test</th></tr></thead><tbody><tr><td><code>files</code></td><td>the backend files that ran, paths only</td></tr><tr><td><code>functions</code></td><td>also the start and end line of each function that ran</td></tr><tr><td><code>lines</code></td><td>also the executed lines</td></tr></tbody></table><p>With <code>functions</code> and <code>lines</code>, each file names its git blob, as <code>git hash-object</code> gives it, which its line numbers refer to. At the end of the run the reporter also sends the run&#39;s coverage of the backend, attributed to no test, with each file&#39;s executable lines at <code>lines</code> granularity. A test whose coverage the backend no longer held, or that could not be collected, is marked incomplete. <code>coverage.browser: &#39;files&#39;</code> is the same as <code>captureCodeReach: true</code>.</p><ul><li><strong>Run level only:</strong> lambdas created at startup (inline minimal API handlers, inline middleware, DI factory lambdas) and work outside a request (hosted services, timers). The methods they call count normally.</li><li><strong>Pages only:</strong> API tests through Playwright&#39;s <code>request</code> fixture record no server coverage.</li><li>C# and Visual Basic only.</li></ul><p>Measured on a prototype, per-test server coverage added under 2% to test duration on Microsoft&#39;s eShopOnWeb, whose CPU goes to the framework, and up to 26% more server CPU on an application that spends its CPU in business logic. Functions cost about what lines cost.</p><h2 id="where-it-is-used" tabindex="-1">Where it is used <a class="header-anchor" href="#where-it-is-used" aria-label="Permalink to &quot;Where it is used&quot;">​</a></h2><ul><li><strong><a href="./test-selection.html#impact-from-diff">Impact-from-diff</a></strong> maps a changed file to the tests that executed it. Code reach only adds tests: a changed source file that no test reached still widens the run to the whole suite, since code reach does not see module top-level code, server code without <a href="#server-code">server coverage</a>, or type-only modules.</li><li><strong><a href="./uncovered-changes.html">Uncovered changes</a></strong> counts a changed file as reached when a test executed it.</li><li><strong><a href="./preflight.html">Locator preflight</a></strong> calls a break <em>likely</em> only when one of its tests reaches the changed file.</li><li><strong><a href="/guide/concepts.html#suspect-lines">Suspect lines</a></strong>: the changed lines a failure&#39;s tests executed, ranked against the passing tests, on the failure pages&#39; <a href="./failure-clusters.html#the-cluster-page">What changed</a> line and diff, in the <a href="./ai-diagnosis.html#scm-grounded-context">AI diagnosis</a> and the <a href="./fix-plans.html">fix plan</a>.</li></ul><p>The dashboard&#39;s API serves the tests reaching one file and the whole map of a branch; see the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a> (<code>/docs</code> on your instance).</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Chromium only</strong> in the browser: other browsers have no JavaScript coverage and record no browser files. Server coverage works with every browser.</li><li><strong>Observed reach, not coverage.</strong> A reached file may hide an untested branch: the unit is the file, never the line.</li><li>A build with neither per-module URLs nor source maps yields nothing, and so does code rendered on the server only, React server components included.</li><li>A module whose top-level code calls its own functions, a table built on import, counts for every test that loads it.</li><li>A function a minifier inlines into another as plain statements counts for the file it was inlined into.</li><li>A test that loads a new document in its page reaches the files of the last document only: Chromium keeps no coverage of a document the page has left. Client-side navigation stays in one document, and an iframe&#39;s earlier documents stay covered.</li><li>Reach is per branch: a branch&#39;s own runs replace its tests&#39; reach, and the default branch&#39;s stands in for the rest.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/capture-fixtures.html">Capture fixtures</a>: what else the fixtures record</li><li><a href="./test-selection.html">Test selection</a>: impact-from-diff</li><li><a href="/guide/privacy.html">Privacy &amp; data flow</a>: what the reporter sends</li></ul>`,37)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
